+    let mockApi: {
+        getReplies: ReturnType<typeof vi.fn>;
+        getPost: ReturnType<typeof vi.fn>;
+    };
+
+    beforeEach(() => {
+        vi.clearAllMocks();
+        
+        (global.fetch as ReturnType<typeof vi.fn>).mockResolvedValue({
+            json: vi.fn().mockResolvedValue({
+                site: {url: 'https://test.com'}
+            })
